describe('Skip-to-content link accessibility', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display skip-to-content link at the top of the page', () => {
    cy.get('a[href="#main-content"]')
      .should('exist')
      .should('be.visible');
  });

  it('should have proper accessibility attributes', () => {
    cy.get('a[href="#main-content"]')
      .should('have.attr', 'class')
      .and('include', 'skip-link');

    cy.get('a[href="#main-content"]')
      .should('have.text', 'Skip to main content');
  });

  it('should focus on skip-to-content link when tabbing from the start', () => {
    cy.get('body').tab();
    cy.focused().should('have.attr', 'href', '#main-content');
  });

  it('should navigate to main content when skip link is clicked', () => {
    cy.get('a[href="#main-content"]').click();
    cy.get('#main-content').should('have.focus');
  });

  it('should be keyboard accessible and properly positioned', () => {
    cy.get('a[href="#main-content"]')
      .should('have.css', 'position')
      .and('match', /absolute|fixed|relative/);

    cy.get('a[href="#main-content"]')
      .invoke('attr', 'tabindex')
      .then((tabindex) => {
        expect(tabindex).to.be.oneOf([null, '0', '1']);
      });
  });

  it('should handle multiple skip links if present', () => {
    cy.get('a[href*="#main"]').each(($link) => {
      cy.wrap($link)
        .should('have.attr', 'href')
        .and('match', /^#/);
    });
  });

  it('should not be visible to mouse users but accessible to keyboard users', () => {
    cy.get('a[href="#main-content"]')
      .should('have.css', 'clip')
      .or('have.css', 'clip-path')
      .or('have.css', 'position', 'absolute');
  });

  it('should have sufficient color contrast for accessibility', () => {
    cy.get('a[href="#main-content"]')
      .should('have.css', 'color')
      .and('not.equal', 'rgba(0, 0, 0, 0)');
  });

  it('should target a valid main content element', () => {
    cy.get('#main-content')
      .should('exist')
      .should('have.attr', 'role', 'main')
      .or('have.tag', 'main');
  });
});
